// Validate input
const { document_id, tenant_id, object_key, filename, content_type, source, metadata } = $json;

if (!document_id || !tenant_id || !object_key) {
  throw new Error('Missing required fields: document_id, tenant_id, object_key');
}

// Return validated data for next nodes
return [{ json: { document_id, tenant_id, object_key, filename, content_type, source, metadata } }];

// Save file to temp for OCR
const fs = require('fs');
const path = require('path');
const os = require('os');

const fileBuffer = $json.data;
const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'gestia-ocr-'));
const ext = path.extname($json.filename) || '.pdf';
const tempPath = path.join(tempDir, `doc${ext}`);

fs.writeFileSync(tempPath, fileBuffer);

return [{ json: { ...$json, temp_path: tempPath, temp_dir: tempDir } }];

// Parse OCR result
const ocrResult = $json;
const text = ocrResult.text || '';
const confidence = ocrResult.confidence || 0;
const metadata = ocrResult.metadata || {};

// Simple classification based on keywords
const textLower = text.toLowerCase();
let tipo = 'otro';
let tipoConfidence = 0.5;

if (textLower.includes('factura') && (textLower.includes('emitida') || textLower.includes('recibida'))) {
  tipo = textLower.includes('emitida') ? 'factura_emitida' : 'factura_recibida';
  tipoConfidence = 0.9;
} else if (textLower.includes('contrato') && textLower.includes('trabajo')) {
  tipo = 'contrato_laboral';
  tipoConfidence = 0.85;
} else if (textLower.includes('escritura') && textLower.includes('pública')) {
  tipo = 'escritura_publica';
  tipoConfidence = 0.9;
} else if (textLower.includes('acta') && textLower.includes('junta')) {
  tipo = 'acta_junta';
  tipoConfidence = 0.85;
} else if (textLower.includes('modelo 303') || textLower.includes('iva')) {
  tipo = 'modelo_303';
  tipoConfidence = 0.8;
} else if (textLower.includes('nómina') || textLower.includes('nomina')) {
  tipo = 'nomina';
  tipoConfidence = 0.85;
}

// Split text into chunks (simple paragraph-based)
const paragraphs = text.split('\n\n').filter(p => p.trim().length > 50);
const chunks = paragraphs.map((p, i) => ({
  index: i,
  content: p.trim(),
  tokens: Math.ceil(p.length / 4),
  page: metadata.page || 1,
  section: `paragraph_${i}`
}));

return [{ json: { ...$json, ocr_text: text, ocr_confidence: confidence, ocr_engine: 'docling', classification: { tipo, confidence: tipoConfidence }, chunks, metadatos: metadata } }];

// Prepare chunk for vector DB
const chunk = $json;
return [{ json: { ...chunk, embedding: $json.embedding } }];

// Cleanup temp files
const fs = require('fs');
const path = require('path');

if ($json.temp_dir && fs.existsSync($json.temp_dir)) {
  fs.rmSync($json.temp_dir, { recursive: true, force: true });
}

return [{ json: $json }];
